input.command:
cat > /tmp/chunk.pl <<'PERLEOF'
use strict; use warnings;
my @args = @ARGV;
pipe(my $r, my $w) or die;
my $pid = fork(); die unless defined $pid;
if ($pid == 0) { close $r; open(STDOUT, '>&', $w) or die; close $w;
  exec('/workspace/dataset/test15_executable', @args); exit 127; }
close $w;
my @chunks; my $buf;
while (1) { my $n = sysread($r, $buf, 65536); last if !defined($n) || $n == 0;
  push @chunks, [$n, $buf]; }
waitpid($pid,0);
printf("PIPE read() calls = %d\n", scalar @chunks);
my $i=0; for my $c (@chunks) { $i++; (my $s=$c->[1]) =~ s/\n/\\n/g;
  printf("  chunk %d: %3d bytes = \"%s\"\n", $i, $c->[0], $s); }
PERLEOF
echo "===== baseline through a PIPE, chunk granularity ====="
perl /tmp/chunk.pl "http" "example.com" "80" "/" "" ""
echo; echo "===== run 5 more times to check stability ====="
for i in 1 2 3 4 5; do perl /tmp/chunk.pl "https" "h.io" "443" "/a/b" "k=v" "frag" | head -1; done

cat > /tmp/chunk2.pl <<'PERLEOF'
use strict; use warnings;
my ($iters, @args) = @ARGV;
my %dist; my %badbound; my $maxn=0; my %boundset;
for my $it (1..$iters) {
  pipe(my $r, my $w) or die;
  my $pid = fork(); die unless defined $pid;
  if ($pid == 0) { close $r; open(STDOUT,'>&',$w) or die; close $w;
    exec('/workspace/dataset/test15_executable', @args); exit 127; }
  close $w;
  my @sizes; my $all=''; my $buf;
  while (1) { my $n = sysread($r,$buf,65536); last if !defined($n)||$n==0;
    push @sizes,$n; $all .= $buf; }
  waitpid($pid,0);
  $dist{scalar @sizes}++;
  $maxn = @sizes if @sizes > $maxn;
  # check every internal boundary lands right after a "\n"
  my $off=0;
  for my $i (0..$#sizes-1) { $off += $sizes[$i];
    $boundset{$off}=1;
    my $ch = substr($all,$off-1,1);
    $badbound{$off}++ if $ch ne "\n"; }
}
print "read-call count distribution: ";
print join(", ", map {"$_ reads x$dist{$_}"} sort {$a<=>$b} keys %dist), "\n";
print "max reads seen = $maxn\n";
my @b = sort {$a<=>$b} keys %boundset;
print "distinct internal boundary byte-offsets observed: @b\n";
if (keys %badbound) { print "!! boundaries NOT after a newline: ", join(",",sort keys %badbound), "\n"; }
else { print "ALL observed write boundaries fall exactly after a '\\n' (line-aligned)\n"; }
PERLEOF
echo "=== 300 iterations, baseline case (expected line-end offsets: 5,17,20,22,23,24,47) ==="
perl /tmp/chunk2.pl 300 "http" "example.com" "80" "/" "" ""
